steps.script:
var main = tree.root.get_node("Main")
var units = GameState.state["units"]
var keep = {"U_CUSTODIAN_GUARD_B": [Vector2(480, 2000), 45.0], "U_BOYZ_K": [Vector2(480, 1400), -45.0], "U_KOMMANDOS_H": [Vector2(480, 720), -45.0]}
for uid in units:
	if keep.has(uid):
		var c = keep[uid][0]
		var step = keep[uid][1]
		var i = 0
		for m in units[uid].get("models", []):
			if not m.get("alive", true):
				continue
			m["position"] = {"x": c.x, "y": c.y + i * step}
			i += 1
		units[uid]["status"] = GameStateData.UnitStatus.DEPLOYED
	else:
		for m in units[uid].get("models", []):
			m["alive"] = false
main._recreate_unit_visuals()
main.get_node("ShootingController")._refresh_unit_list(false)
return "ok"

var b = GameState.create_snapshot(false)
var a = RulesEngine.unit_sight_line("U_CUSTODIAN_GUARD_B", "U_BOYZ_K", b)
var c = RulesEngine.unit_sight_line("U_CUSTODIAN_GUARD_B", "U_KOMMANDOS_H", b)
return "%s|%s" % [str(a.has_los), str(c.has_los)]

var list = tree.root.get_node("Main/HUD_Right/VBoxContainer/ShootingScrollContainer/ShootingPanel/DeclarationBox/ShooterUnitList")
if list.item_count < 1 or not list.get_item_text(0).begins_with("Custodian Guard"):
	return "row 0 is not Custodian Guard"
return "ok"

var lv = tree.root.get_node("Main/BoardRoot/LoSDebugVisual")
var hits = []
for ol in lv.overview_lines:
	hits.append("%s:%s:%s" % [ol["tgt"], ol["verdict"], str(ol["reason"] != "")])
return "|".join(hits)

var lv = tree.root.get_node("Main/BoardRoot/LoSDebugVisual")
lv.set_debug_enabled(true)
lv.show_overview("U_CUSTODIAN_GUARD_B")
var out = {}
for ol in lv.overview_lines:
	out[ol["tgt"]] = ol["verdict"]
return "%s|%s" % [str(out.get("U_BOYZ_K", "missing")), str(out.get("U_KOMMANDOS_H", "missing"))]

var lv = tree.root.get_node("Main/BoardRoot/LoSDebugVisual")
for ol in lv.overview_lines:
	if ol["tgt"] == "U_KOMMANDOS_H":
		return ol["reason"]
return "no line"

var lv = tree.root.get_node("Main/BoardRoot/LoSDebugVisual")
var board = GameState.create_snapshot(false)
var mismatches = 0
for ol in lv.overview_lines:
	var src = str(ol.get("src", "U_CUSTODIAN_GUARD_B"))
	var tgt = str(ol.get("tgt", ""))
	if tgt == "":
		for uid in ["U_BOYZ_K", "U_KOMMANDOS_H"]:
			for m in board["units"][uid]["models"]:
				if m.get("alive", true) and Vector2(m["position"]["x"], m["position"]["y"]).distance_to(ol["to"]) < 40.0:
					tgt = uid
	var green = str(ol.get("verdict", "targetable" if ol["is_clear"] else "blocked")) == "targetable"
	var elig = RulesEngine.get_eligible_targets(src, board)
	if green != elig.has(tgt):
		mismatches += 1
return mismatches

var m = tree.root.get_node("Main")
m._open_settings_menu()
return m._settings_menu != null

var lv = tree.root.get_node("Main/BoardRoot/LoSDebugVisual")
lv.set_debug_enabled(true)
lv.show_overview("U_CUSTODIAN_GUARD_B")
var rows = []
for ol in lv.overview_lines:
	rows.append("%s:%s" % [ol["tgt"], ol["verdict"]])
return "|".join(rows)

var m = tree.root.get_node("Main")
m._open_settings_menu()
return m._settings_menu != null

var lv = tree.root.get_node("Main/BoardRoot/LoSDebugVisual")
lv.show_overview("U_CUSTODIAN_GUARD_B")
var rows = []
for ol in lv.overview_lines:
	rows.append("%s:%s" % [ol["tgt"], ol["verdict"]])
return "|".join(rows)
